  },
  "servers": [
    {
      "url": "https://api-sandbox.modulrfinance.com/api-sandbox-token"
    }
  ],
  "security": [
    {
      "modulo_security": []
    }
  ],
  "paths": {
    "/bulk-cards/upload": {
      "post": {
        "tags": [
          "Cards Bulk Operations"
        ],
        "summary": "Upload CSV file with bulk card operations",
        "description": "Allow clients to upload csv file with create, update and change card status requests",
        "operationId": "uploadBulkCards",
        "parameters": [
          {
            "name": "validateOnly",
            "in": "query",
            "description": "Flag of whether to validate batch entries and not submit for processing. Default false.",
            "required": false,
            "style": "form",
            "explode": true,
            "schema": {
              "type": "boolean",
              "default": false
            }
          },
          {
            "name": "keepEntries",
            "in": "query",
            "description": "Flag of whether to persist entries for batch request. Can only be true if validateOnly is true, default is false",
            "required": false,
            "style": "form",
            "explode": true,
            "schema": {
              "type": "boolean",
              "default": false
            }
          },
          {
            "name": "overrideFile",
            "in": "query",
            "description": "Flag of whether to replace existing file with same name. Default false.",
            "required": false,
            "style": "form",
            "explode": true,
            "schema": {
              "type": "boolean",
              "default": false
            }
          }
        ],
        "requestBody": {
          "content": {
            "multipart/form-data": {
              "schema": {
                "type": "object",
                "properties": {
                  "file": {
                    "type": "string",
                    "format": "binary",
                    "description": "CSV file containing bulk card operations"
                  }
                },
                "required": [
                  "file"
                ]
              }
            }
          }
        },
        "responses": {
          "202": {
            "description": "CSV file accepted and validated",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/card.BulkCardsOpsResponse"
                }
              }
            }
          },
          "400": {
            "description": "Invalid request",
            "content": {
              "*/*": {
                "schema": {
                  "type": "array",
                  "items": {
                    "$ref": "#/components/schemas/card.MessageResponse"
                  }
                }
              }
            }
          },
          "403": {
            "description": "Forbidden. Incorrect permissions",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/card.BulkCardsOpsResponse"
                }
              }
            }
          }
        },
        "security": [
          {
            "HMAC": []
          },
          {
            "TOKEN": []
          }
        ]
      }
    }
  },
  "components": {
    "schemas": {
      "card.BulkCardsOpsResponse": {
        "type": "object",
        "properties": {
          "bulkRequestId": {
            "type": "string"
          },
          "submissionTimestamp": {
            "type": "string",
            "format": "date-time"
          },
          "status": {
            "type": "string",
            "enum": [
              "SUBMITTED",
              "VALIDATED",
              "VALIDATED_WITH_ERRORS",
              "PROCESSING",
              "PARTIALLY_PROCESSED_WITH_ERRORS",
              "PARTIALLY_PROCESSED",
              "PROCESSED",
              "ARCHIVED",
              "DELETED"
            ]
          }
        }
      },
      "card.MessageResponse": {
        "type": "object",
        "properties": {
          "field": {
            "type": "string"
          },
          "code": {
            "type": "string",
            "enum": [
              "GENERAL",
              "BUSINESSRULE",
              "MFASTATUS",
              "MFAERROR",
              "MFATIMEOUT",
              "MFADEVICEMM",
              "MFAMESSAGEINVALID",
              "NOTFOUND",
              "DUPLICATE",
              "INVALID",
              "CONNECTION",
              "RETRY",
              "RATELIMIT",
              "PERMISSION",
              "NOTACCEPTABLE",
              "MFAVERIFICATION",
              "TOKENEXPIRED"
            ]
          },
          "errorCode": {
            "type": "string"
          },
          "message": {
            "type": "string"
          },
          "sourceService": {
            "type": "string"
          }
        }
      }
    },
    "securitySchemes": {
      "modulo_security": {
        "type": "apiKey",
        "name": "Authorization",
        "in": "header"
      },
      "TOKEN": {
        "type": "apiKey",
        "name": "Authorization",
        "in": "header"
      }
    }
  },
  "x-readme": {
    "proxy-enabled": false
  }
}
